final class TechThemeDemoData
{
 public function catalog(Request $request): array {
  $category=new Category(['name'=>'Audio','slug'=>'demo-tech','description'=>'Headphones, earbuds and accessories for everyday listening.','image_url'=>asset('images/themes/tech/hero.png')]);$category->id=-2;
  $rows=[['Orbit Pro Wireless Headphones','headphones',89900,'Graphite'],['Air Buds Pro','earbuds',49900,'Black'],['Connect USB-C Hub','hub',22900,'Silver'],['Pulse Mini Bluetooth Speaker','speaker',34900,'Black'],['Studio Wired Headphones','headphones',29900,'Graphite'],['Air Buds Lite','earbuds',19900,'Silver']];
  $products=collect($rows)->map(function($r,$i)use($category){
   $image=asset('images/themes/tech/'.$r[1].'.png');
   $p=new Product(['title'=>$r[0],'handle'=>'theme-demo-tech-'.$r[1],'brand'=>'JW STUDIO','status'=>'active','subtitle'=>$i===0?'Wireless listening. Everyday precision.':'Designed for your connected everyday.','base_price'=>$r[2],'description'=>'','options'=>[['name'=>'Colour','values'=>[$r[3]],'displayType'=>'pills']]]);$p->id=-200-$i;
   $im=new ProductImage(['path'=>$image,'alt'=>$r[0],'position'=>0]);$im->id=-2000-$i;
   $v=new ProductVariant(['title'=>$r[3],'sku'=>'DEMO-TECH-'.$i,'price'=>$r[2],'stock'=>25,'enabled'=>true,'options'=>['Colour'=>$r[3]]]);$v->id=-2000-$i;$v->setRelation('product',$p);
   $variants=collect([$v]);$images=collect([$im]);
   if($i===0){$p->options=[['name'=>'Colour','values'=>['Graphite','Silver'],'displayType'=>'color_palette','valueVisuals'=>['Graphite'=>['visualType'=>'color','colorCode'=>'#343840'],'Silver'=>['visualType'=>'color','colorCode'=>'#c4c9d1']]]];$v->color_code='#343840';$v->visual_type='color';$silver=new ProductVariant(['title'=>'Silver','sku'=>'DEMO-TECH-SILVER','price'=>89900,'stock'=>25,'enabled'=>true,'options'=>['Colour'=>'Silver'],'color_code'=>'#c4c9d1','visual_type'=>'color']);$silver->id=-2300;$silver->setRelation('product',$p);$variants->push($silver);$extra=new ProductImage(['path'=>asset('images/themes/tech/hero.png'),'alt'=>'Orbit Pro details','position'=>1]);$extra->id=-2400;$images->push($extra);}
   return $p->setRelation('category',$category)->setRelation('images',$images)->setRelation('variants',$variants)->setRelation('pdpContent',new ProductPdpContent(['highlights'=>[['id'=>'audio','text'=>'Active noise cancellation','icon'=>'audio-lines'],['id'=>'battery','text'=>'Up to 40 hours','icon'=>'battery'],['id'=>'usb','text'=>'USB-C charging','icon'=>'usb']],'specifications'=>[['id'=>'driver','label'=>'Driver','value'=>'40 mm'],['id'=>'connectivity','label'=>'Connectivity','value'=>'Bluetooth 5.3'],['id'=>'battery','label'=>'Battery life','value'=>'Up to 40 hours'],['id'=>'weight','label'=>'Weight','value'=>'250 g']],'custom_accordions'=>[['id'=>'compatibility','title'=>'Compatibility','content'=>'Compatible with Bluetooth audio devices.'],['id'=>'box','title'=>"What's in the box",'content'=>'Headphones, charging cable and protective case.'],['id'=>'care','title'=>'Care & support','content'=>'Keep clean and dry.']],'story'=>['heading'=>'Precision sound for everyday life','description'=>'Designed for clarity, comfort and everyday listening.','image'=>asset('images/themes/tech/hero.png')]]))->setRelation('reviews',collect())->setRelation('pdpRelatedProducts',collect());
  });
  $request->attributes->set('websiteThemeDemoVariants',$products->flatMap(fn($p)=>$p->variants)->all());$request->attributes->set('websiteThemeDemoProducts',$products);
  $min=max(19900,$request->integer('min_price',19900));$max=min(89900,$request->integer('max_price',89900));$sort=$request->input('sort','');$colors=array_values(array_filter((array)$request->input('color',[]),'is_string'));$visible=$products->filter(fn($p)=>$p->base_price>=$min&&$p->base_price<=$max);$visible=$visible->filter(fn($p)=>$colors===[]||$p->variants->contains(fn($v)=>in_array(strtolower($v->title),$colors,true)));if($sort==='price_asc')$visible=$visible->sortBy('base_price');if($sort==='price_desc')$visible=$visible->sortByDesc('base_price');
  $filters=['search'=>'','category'=>null,'sort'=>$sort,'layout'=>'grid','minPrice'=>$min,'maxPrice'=>$max,'boundsMinPrice'=>19900,'boundsMaxPrice'=>89900,'priceRequested'=>$min!==19900||$max!==89900,'inStock'=>$request->boolean('in_stock'),'colors'=>$colors,'materials'=>[],'minRating'=>0,'variantFiltered'=>false];
  $facets=['priceBounds'=>['min'=>19900,'max'=>89900],'total'=>6,'categoryCounts'=>[-2=>6],'colors'=>[['value'=>'graphite','label'=>'Graphite','hex'=>'#343840','count'=>2],['value'=>'silver','label'=>'Silver','hex'=>'#c4c9d1','count'=>3]],'materials'=>[],'hasRatings'=>false,'ratings'=>[]];
  return (new CatalogFilterResult($filters,new LengthAwarePaginator($visible->values(),$visible->count(),12),$facets))->toViewData()+['demoTheme'=>'tech','categories'=>collect([$category]),'collection'=>null,'listingCategory'=>$category,'catalogListingSettings'=>['title'=>$category->name,'description'=>$category->description],'listingRouteName'=>'admin.website-design.preview','listingRouteParameters'=>['theme'=>'tech','surface'=>'plp'],'demoProducts'=>$products];
 }
